 // OMEGA-BLOCK-START
 // Sorts a[0..n) ascending, in place, on the calling thread. n is any size from
 // 0 to 2'000'000. Extra memory may be allocated freely.
+constexpr size_t MAX_N = 2000005;
+constexpr size_t MERGE_THRESHOLD = 32;
+
+static void insert_sort(uint32_t* a, size_t lo, size_t hi) {
+    for (size_t i = lo + 1; i < hi; ++i) {
+        uint32_t key = a[i];
+        size_t j = i;
+        while (j > lo && a[j - 1] > key) {
+            a[j] = a[j - 1];
+            --j;
+        }
+        a[j] = key;
+    }
+}
+
 static void merge_sort_rec(uint32_t* a, uint32_t* tmp, size_t lo, size_t hi) {
-    if (hi - lo < 2) return;
+    size_t len = hi - lo;
+    if (len <= MERGE_THRESHOLD) {
+        insert_sort(a, lo, hi);
+        return;
+    }
+    if (len < 2) return;
     size_t mid = lo + (hi - lo) / 2;
     merge_sort_rec(a, tmp, lo, mid);
     merge_sort_rec(a, tmp, mid, hi);
